package com.vandorlabs.client;
import com.google.gson.*;
import com.vandorlabs.blocks.*;
import com.vandorlabs.tiles.*;
import net.minecraft.block.*;
import net.minecraft.block.material.Material;
import net.minecraft.block.state.IBlockState;
import net.minecraft.nbt.*;
import net.minecraft.util.*;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.*;
/** Individual actual getter costs; renderer call order is frozen separately without substituting guessed roles. */
public final class ScreenGetterQueriesLegacyChecks {
 private static int reads;
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();Block probe=new Block(Material.ROCK){@Override public boolean shouldCheckWeakPower(IBlockState state,IBlockAccess world,BlockPos pos,EnumFacing side){return false;}@Override public int getWeakPower(IBlockState state,IBlockAccess world,BlockPos pos,EnumFacing side){reads++;return 7;}};net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityAnimatedScreenSelector.class,new ResourceLocation("minecraft:screen_getter_queries_reference"));JsonObject reference;try(java.io.Reader reader=java.nio.file.Files.newBufferedReader(java.nio.file.Paths.get("build/test-artifacts/screen-light-queries-reference.json"))){reference=new JsonParser().parse(reader).getAsJsonObject();}if(!reference.get("sha256").getAsString().equals("a9fa6a51eff6f2984fb3c275134643390aeb4bb28dc80bf385621984e67edc67"))throw new AssertionError("Light source changed");JsonArray output=new JsonArray();int index=0;for(JsonElement element:reference.getAsJsonArray("cases")){JsonObject base=element.getAsJsonObject();BlockAnimatedScreenSelector block=null;for(Block candidate:ModBlocks.BLOCKS)if(candidate.getRegistryName().getResourcePath().equals(base.get("id").getAsString()))block=(BlockAnimatedScreenSelector)candidate;int sourceIndex=index++;if(base.get("meta").getAsInt()!=block.getMetaFromState(block.getDefaultState()))continue;NBTTagCompound saved=JsonToNBT.getTagFromJson(base.get("saved").getAsString());for(boolean split:new boolean[]{false,true})for(boolean small:new boolean[]{false,true}){TileEntityAnimatedScreenSelector tile=(TileEntityAnimatedScreenSelector)block.createNewTileEntity(null,0);NBTTagCompound data=saved.copy();data.setBoolean("DisplaySplit",split);data.setBoolean("smallInput",small);tile.readFromNBT(data);NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);BlockPos pos=new BlockPos(0,80,0);world.states.put(pos,block.getDefaultState());world.states.put(pos.up(),probe.getDefaultState());world.tiles.put(pos,tile);tile.setWorld(world);tile.setPos(pos);JsonArray values=new JsonArray(),costs=new JsonArray();for(int operation=0;operation<13;operation++){if(tile.joinedDisplayPower!=null)tile.joinedDisplayPower.powerChanged();reads=0;values.add(value(tile,operation));costs.add(reads);}JsonObject row=new JsonObject();row.addProperty("case",sourceIndex);row.addProperty("split",split);row.addProperty("small",small);row.add("values",values);row.add("reads",costs);output.add(row);}}String text=output.toString();java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");StringBuilder digest=new StringBuilder();for(byte b:hash.digest(text.getBytes("UTF-8")))digest.append(String.format("%02x",b&255));if(!digest.toString().equals("13b18754c83e1741147f020d6b663567bb973bd1721e79144a96dafd09235a42"))throw new AssertionError("Actual getter queries changed "+digest);JsonObject root=new JsonObject();root.addProperty("sha256",digest.toString());root.addProperty("lightSha256",reference.get("sha256").getAsString());root.add("cases",output);java.nio.file.Path path=java.nio.file.Paths.get("build/test-artifacts/screen-getter-queries-reference.json");java.nio.file.Files.write(path,root.toString().getBytes("UTF-8"));System.out.println("Actual Screen getter queries reference PASS profiles="+output.size()+" getters="+(output.size()*13)+" sha256="+digest);}
 private static int value(TileEntityAnimatedScreenSelector tile,int operation){switch(operation){case 0:return tile.getSignalLevel();case 1:return tile.activationState();case 2:return tile.getEffectiveMode();case 3:return tile.getSurfaceTexture(0);case 4:return tile.getSurfaceTexture(1);case 5:return tile.effectiveMode(0);case 6:return tile.effectiveMode(1);case 7:return tile.effectiveSpeed(0);case 8:return tile.effectiveSpeed(1);case 9:return tile.activationOverridesArtwork()?1:0;case 10:return tile.splitDisplay()?1:0;case 11:return tile.primaryArtworkTexture();default:return tile.getAnimationSpeedIndex();}}
}
